   "id": "expenses-identity",
   "chapter": "expenses",
   "title": "Who is asking",
   "stages": [
    "authenticate"
   ],
   "narration": "The identity is the user whose API token is the bearer token of the request. The auth function answers who is asking, and nothing else. Its return type becomes the type of auth in every policy and hook.",
   "audio": "audio/expenses-identity.mp3",
   "duration": 14.2,
   "panel": {
    "kind": "file",
    "path": "examples/expenses/src/app.ts",
    "language": "typescript",
    "start": 1,
    "code": "import { defineApp } from 'blendx';\nimport { sql } from 'blendx/drizzle';\nimport { models } from './generated/schema.gen.ts';\n\nconst BEARER = /^Bearer ([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/i;\n\nexport default defineApp({\n  /**\n   * The identity is the user whose api_token is the request's bearer token. Without a token,\n   * or with one nobody has, there is no identity, and actions that need one answer 401.\n   */\n  auth: async ({ request, db }): Promise<{ id: number; is_approver: boolean } | null> => {\n    const token = BEARER.exec(request.headers.get('authorization') ?? '')?.[1];\n    if (!token) return null;\n    const users = models.users.table;\n    const [user] = await db\n      .select({ id: users.id, is_approver: users.is_approver })\n      .from(users)\n      .where(sql`${users.api_token} = ${token}`)\n      .limit(1);\n    return user ?? null;\n  },\n});",
    "highlight": [
     12,
     21
    ]
   }
